j:jelly.g:evaluate:
		var isA11yEnabled = GlideAccessibility.isEnabled();
        var cxsResults = jelly.jvar_cxs_response.results;
		var searchTerm = GlideStringUtil.escapeHTML(jelly.jvar_cxs_response.request.query.freetext);
		var statusMsg = "";
		var windowStart = jelly.jvar_cxs_response.request.meta.window.start;
		var ariaMsg = "";
		if (JSUtil.nil(cxsResults)) {
			cxsResults = [];
			statusMsg = gs.getMessage("No matching results found for");
			ariaMsg = gs.getMessage("No matching results found for {0}", searchTerm);
		}else {
			if(isA11yEnabled) 
				ariaMsg = gs.getMessage("Showing search results from {0} to {1} for {2}", [windowStart + 1 + "", windowStart + cxsResults.length + "", searchTerm]);
		}

        var cxsDocType = jelly.jvar_cxs_response.request.meta.is_doctype;

var table = jelly.jvar_cxs_response.request.meta.source_table;
var display =  "display: " + gs.getPreference(table + ".cxs_search_results.display", "block");
display;

j:forEach.g:evaluate:
// we are doing this for backward compatibility as csm team has their own macros which are relying on these values.
var cxsActionLabel = '';
var cxsActionValue = '';
var thisHelpedActionDetails = (jelly.jvar_cxs_result.searchResultActions && jelly.jvar_cxs_result.searchResultActions.this_helped) ? JSON.parse(jelly.jvar_cxs_result.searchResultActions.this_helped) : null;
if (thisHelpedActionDetails != null) {
	cxsActionLabel = thisHelpedActionDetails.actionLabel;
	cxsActionValue = thisHelpedActionDetails.actionValue;
}
